const GRID_SIZE = 4
const SURFACE_PADDING = 40
const DEFAULT_NODE_WIDTH = 160
const DEFAULT_NODE_HEIGHT = 72
const ENTITY_FIELD_HEIGHT = 20
const ENTITY_HEADER_HEIGHT = 48
const RANK_GAP = 96
const NODE_GAP = 48
const SEQUENCE_COLUMN_GAP = 56
